/* Consequences: not interventions. Shown so teachers can tell the difference. */
var CONSEQUENCES = [
  { name: "Lunch or after-school detention", why: "Imposes a penalty after the behavior; teaches no replacement skill." },
  { name: "Loss of privilege (recess, free time)", why: "A penalty; may be appropriate per the matrix, but it is not an intervention." },
  { name: "Restitution (cleaning, paying for damage)", why: "Repairs the damage, but it is a consequence. Pair it with a restorative conversation." },
  { name: "Forced apology / apology letter", why: "A consequence. A restorative conversation that the student leads is the intervention." },
  { name: "Removal from class / office time-out", why: "A consequence. If the student is escaping work, removal can reinforce the behavior." },
  { name: "Moving a clip/color down or losing points", why: "A penalty (response cost); use only after supportive strategies are tried (Conroy & Sutherland, 2012)." },
  { name: "Call home only to report behavior", why: "Parent communication is required for Level 2 behaviors, but a report alone is not an intervention. Share the plan and ask for partnership." },
  { name: "Office referral, suspension, or expulsion", why: "Administrator consequences for Level 3 and 4 behaviors. Suspension is linked to poorer outcomes (Noltemeyer, Ward, & Mcloughlin, 2015)." }
];

